# LVX ISA support for gem5 — CPU bindings (ArchISA/MMU/Interrupts/Decoder).
# SPDX-License-Identifier: BSD-3-Clause

from m5.objects.BaseAtomicSimpleCPU import BaseAtomicSimpleCPU
from m5.objects.BaseMinorCPU import (
    BaseMinorCPU,
    MinorFU,
    MinorFUPool,
    minorMakeOpClassSet,
)
from m5.objects.BaseNonCachingSimpleCPU import BaseNonCachingSimpleCPU
from m5.objects.BaseTimingSimpleCPU import BaseTimingSimpleCPU

# Pipeline stages generated by BE/GEM5 from Processor.table; a result written at
# stage S has dependence latency S - LVX_STAGE_RR.
from m5.objects.lvx_stages import (
    LVX_MAX_BUNDLE_ISSUE,
    LVX_MIN_TAKEN,
    LVX_STAGE_E1,
    LVX_STAGE_E2,
    LVX_STAGE_E3,
    LVX_STAGE_E4,
    LVX_STAGE_FD,
    LVX_STAGE_RR,
    LVX_STAGE_SF,
    LVX_STAGE_SR,
)
from m5.objects.LvxDecoder import LvxDecoder
from m5.objects.LvxInterrupts import LvxInterrupts
from m5.objects.LvxISA import LvxISA
from m5.objects.LvxMMU import LvxMMU


class LvxCPU:
    ArchDecoder = LvxDecoder
    ArchMMU = LvxMMU
    ArchInterrupts = LvxInterrupts
    ArchISA = LvxISA


class LvxAtomicSimpleCPU(BaseAtomicSimpleCPU, LvxCPU):
    mmu = LvxMMU()


class LvxNonCachingSimpleCPU(BaseNonCachingSimpleCPU, LvxCPU):
    mmu = LvxMMU()


class LvxTimingSimpleCPU(BaseTimingSimpleCPU, LvxCPU):
    mmu = LvxMMU()


# Functional units as latency buckets, one per pipeline write stage. There has
# to be one per *distinct* write stage, and FD was missing until 2026-10-19:
# the nine FDIV*/FSQRT* opcodes write at FD, a latency of 13, and with no
# bucket for it they fell into the next one down and were modelled at 11. Two
# cycles short on every floating-point divide and square root, and the kind of
# gap that closes silently -- the routing below has no way to say "no bucket
# fits", it just picks a lower one.
#
# A result written at stage S has dependence latency S - LVX_STAGE_RR
# (lvx_stages.h), and each micro-op is routed to the FU whose opLat matches its
# own result latency, keyed by a bucket OpClass. Those OpClasses are routing
# labels, not semantics -- the per-opcode latency already separates e.g. FP16
# (E3) from FP32/FP64 (E4) FADD/FMUL/FFMA. issueLat 1 keeps each lane
# pipelined, so a bundle may issue every cycle, and srcRegsRelativeLats
# defaults to 0 so the RAW issue distance is exactly opLat = write stage - RR.
#
# Every bucket gets LVX_MAX_BUNDLE_ISSUE *lanes*, which one did not before the
# micro-op split and had to after it. A bundle used to be one instruction and
# so occupied one FU; its syllables are separate instructions now, all of them
# may land in the same latency bucket, and a MinorFU accepts one instruction
# per cycle (`alreadyPushed'). With a single lane a bundle holding two ALU
# syllables issued over two cycles -- every dependence chain a cycle longer
# than the machine's, measurably: the mulw chain cost 3 where it costs 2.
#
# These are not a resource model. The assembler's bundling rules already
# guarantee a legal bundle has no resource conflict, so re-imposing one here
# could only invent a hazard the hardware does not have; the lanes exist so
# that a bundle the hardware issues in one cycle is issued in one cycle.
def _lvxFU(name, op_class, write_stage):
    return type(name, (MinorFU,), dict(
        opClasses=minorMakeOpClassSet([op_class]),
        opLat=write_stage - LVX_STAGE_RR,
        issueLat=1,
    ))


# Cheapest first: Execute scans the pool in order for a capable free unit, so
# the bucket most instructions want should be found without walking the rest.
_LVX_BUCKETS = [
    _lvxFU("LvxFU_E1", "IntAlu",    LVX_STAGE_E1),
    _lvxFU("LvxFU_E2", "IntMult",   LVX_STAGE_E2),
    _lvxFU("LvxFU_E3", "FloatAdd",  LVX_STAGE_E3),
    _lvxFU("LvxFU_E4", "FloatMult", LVX_STAGE_E4),
    _lvxFU("LvxFU_SF", "FloatDiv",  LVX_STAGE_SF),
    _lvxFU("LvxFU_FD", "FloatSqrt", LVX_STAGE_FD),
    _lvxFU("LvxFU_SR", "IntDiv",    LVX_STAGE_SR),
]


class LvxFUPool(MinorFUPool):
    funcUnits = [
        fu() for fu in _LVX_BUCKETS for _ in range(LVX_MAX_BUNDLE_ISSUE)
    ]


# In-order pipeline model. Consumes LvxStaticInst's src/dest register lists to
# stall a bundle until its sources are produced (RAW hazards) and applies the
# LvxFUPool latencies above -- the model that turns the dependency lists into
# cycle counts. LVX is a statically scheduled in-order VLIW, so an in-order
# pipeline is the right abstraction (one bundle issues per cycle unless stalled).
# See docs/register-buffer-deps.md.
class LvxMinorCPU(BaseMinorCPU, LvxCPU):
    mmu = LvxMMU()
    executeFuncUnits = LvxFUPool()
    # A taken branch costs LVX_MIN_TAKEN cycles beyond its own bundle before the
    # target's first bundle issues (Processor@minTaken, generated into
    # lvx_stages.py). LVX resolves branches in the pipeline and does not predict
    # them, so this is a constant, not a misprediction penalty -- and it has to
    # be charged explicitly, because MinorCPU's own taken-branch cost is its
    # front-end refill, which is both deeper than LVX's and nearly free here
    # once the branch predictor has learned a loop. Measured before this:
    # 0.2 cycles per taken branch, i.e. nothing.
    #
    # The predictor stays on deliberately: it stands in for an LVX fetch engine
    # that keeps up with a taken branch, leaving this parameter as the whole of
    # the penalty. The modelling residue is a *mispredicted* branch, which also
    # pays Minor's refill -- first execution of each branch and each loop exit,
    # so a warm loop is unaffected.
    takenBranchBubble = LVX_MIN_TAKEN
    # One bundle per cycle, and a whole bundle at a time.
    #
    # A bundle is a macroop whose syllables are micro-ops, so the pipeline
    # carries up to LVX_MAX_BUNDLE_ISSUE instructions where it used to carry
    # one. MinorCPU's defaults (2 everywhere) then split a bundle across
    # cycles, which is wrong in both directions at once: a 3-syllable bundle
    # took two cycles to issue, and two one-syllable bundles could issue in
    # the same cycle.
    #
    # So the widths and limits downstream of Decode are a whole bundle, and
    # the one-bundle-per-cycle rule is applied at *issue*
    # (executeOneMacroopPerCycle) rather than by narrowing the front end.
    # That distinction cost a day: capping Decode's input at one bundle a
    # cycle does make issue one bundle a cycle, but it also stops the front
    # end from ever running ahead -- so a redirect's turnaround never closes
    # and every loop paid it on every trip. The hardware loop, which has no
    # branch at all and whose back edge is free, went from 7 cycles a trip to
    # 10. The front end has to be allowed to run ahead; what must not happen
    # is two bundles issuing together.
    executeInputWidth = LVX_MAX_BUNDLE_ISSUE
    executeIssueLimit = LVX_MAX_BUNDLE_ISSUE
    executeCommitLimit = LVX_MAX_BUNDLE_ISSUE
    executeOneMacroopPerCycle = True
    # Loads and stores go through the load/store queue, so the data cache
    # sees them -- until 2026-10-20 the shim served every access functionally
    # inside the behaviour and the D-cache's counters were all zero whatever
    # the program did.
    #
    # The ISA still states the dependence latency: `ld' returns at CR and
    # `ld.u' at SR, so a consumer waits 3 or 15 cycles, not whatever the
    # memory system happens to cost. The access can still take *longer* --
    # in-order commit waits for the response too, so a cache miss shows --
    # which makes this a floor rather than a replacement. Lifting it, so that
    # the hierarchy alone decides, is a modelling decision about what the
    # description's 15 cycles means when the configuration has no L2.
    executeMemRefsAssumeFixedLatency = True
    # The early mem-issue path is what cannot coexist with non-blocking
    # functional units: it reaches for the instruction at its FU's end, and a
    # non-blocking unit has already let it go. Normal in-order commit of a
    # memory reference never consults the FU, so switching this off is what
    # lets the load shadow and the queue both work.
    executeAllowEarlyMemoryIssue = False
    # Deliberately permissive. Two LSU slots issue per cycle, and a load
    # shadow means several accesses in flight at once -- an uncached load is
    # 15 cycles and a bundle may issue every cycle. Sized so that the queues
    # themselves are not the first thing a program hits; the L1's four MSHRs
    # are the real limit on concurrency. Tightening these to a machine is a
    # separate exercise, and wants measurements rather than guesses.
    executeLSQRequestsQueueSize = 2
    executeLSQTransfersQueueSize = 8
    executeLSQStoreBufferSize = 8
    executeMaxAccessesInMemory = 8
    # The architectural bound here is the LSU availability (2), not the issue
    # width -- but nothing is routed through the LSQ yet, so these are inert;
    # they are set permissive rather than wrong, and want the real bound when
    # memory accesses start reaching it.
    executeMemoryIssueLimit = LVX_MAX_BUNDLE_ISSUE
    executeMemoryCommitLimit = LVX_MAX_BUNDLE_ISSUE
    # LVX writes each result at its own pipeline stage (E1 … SR) and interlocks
    # the consumer -- out-of-order writeback with in-order issue -- which is the
    # whole premise of scheduling independent work into a long operation's
    # shadow. MinorCPU's default is in-order writeback: an FU self-stalls the
    # moment an instruction reaches its end that in-order commit is not ready
    # for, and one 1-cycle addd behind a 15-cycle ld.u then blocks every later
    # ALU instruction. So there was no shadow at all -- `ld.u; N fillers; use'
    # cost 15 + N + 1 where the machine costs max(N + 1, 15) + 1, and an
    # *independent* instruction after an uncached load cost 8.4 cycles instead
    # of 1. With this the instruction leaves its FU when its own latency
    # expires and waits its turn in the in-flight queue, commit staying in
    # order; the dependence latencies, the taken-branch penalty and the
    # hardware-loop cost are all unchanged, measurably.
    nonBlockingFuncUnits = True
